parameters.jsCode:
// 1. Ambil teks output dari AI Agent
let text = "";
if (typeof $input.item.json.output === 'string') {
  text = $input.item.json.output;
} else if (typeof $input.item.json.output === 'object') {
  text = JSON.stringify($input.item.json.output);
}

// 2. Fungsi pembantu untuk ekstrak data berdasarkan label secara fleksibel
function extractValue(regex, defaultValue = "Not Specified") {
  const match = text.match(regex);
  if (match && match[1] && match[1].trim() !== "") {
    return match[1].replace(/[\*\_\#]/g, "").trim();
  }
  return defaultValue;
}

// 3. Ekstraksi Dinamis
// Menangkap nilai setelah tanda titik dua (:) pada label baku
let propName = extractValue(/(?:Property Name|Property)\s*[:\-\=]\s*([^\n\r\-]+)/i);
let noi = extractValue(/(?:NOI Value|NOI|Net Operating Income)\s*[:\-\=]\s*([^\n\r\-]+)/i);
let dscr = extractValue(/(?:DSCR Ratio|DSCR|Debt Coverage Ratio)\s*[:\-\=]\s*([^\n\r\-]+)/i);
let risk = extractValue(/(?:Risk Summary|Risk Factors|Primary Risk)\s*[:\-\=]\s*([^\n\r\-]+)/i);
let rec = extractValue(/(?:Underwriting Recommendation|Recommendation)\s*[:\-\=]\s*([^\n\r\-]+)/i);

// 4. Pastikan DSCR memiliki akhiran 'x' jika hanya berupa angka
if (dscr !== "Not Specified" && !dscr.toLowerCase().includes('x')) {
  dscr += "x";
}

// 5. Kembalikan data murni dari PDF
return {
  json: {
    property_name: propName,
    noi_value: noi,
    dscr_ratio: dscr,
    risk_summary: risk,
    underwriting_recommendation: rec
  }
};

